def cycle(n):
    # n nodes in a ring, each connected to the next and the previous
    return [[(i - 1) % n, (i + 1) % n] for i in range(n)]
def complete_bipartite(left, right):
    # nodes 0..left-1 are each connected to nodes left..left+right-1, and the other way round
    return [list(range(left, left + right)) for _ in range(left)] + [list(range(left)) for _ in range(right)]
